const STOP_WORDS = new Set(['the','a','an','of','to','in','on','at','for','with','and','or','is','are','was','were','from','by','his','her','their']);

function scoreMatch(tokens, captionLower) {
  let score = 0;
  for (const tok of tokens) {
    if (!tok || STOP_WORDS.has(tok)) continue;
    const reWord = new RegExp('\\b' + tok.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '\\b', 'i');
    if (reWord.test(captionLower)) {
      score += 10;
    } else if (captionLower.includes(tok)) {
      score += 4;
    }
  }
  return score;
}

export async function onRequestGet(context) {
  const url = new URL(context.request.url);
  const q = (url.searchParams.get('q') || '').trim();
  if (!q) {
    return new Response(JSON.stringify({ ok: false, error: 'missing_query' }), {
      status: 400,
      headers: { 'Content-Type': 'application/json', 'Access-Control-Allow-Origin': '*' }
    });
  }

  const tokens = q.toLowerCase().replace(/[^a-z0-9\s]/g, ' ').split(/\s+/).filter(Boolean);
  let best = null;
  let bestScore = 0;

  for (const item of WOL_CATALOG) {
    const s = scoreMatch(tokens, item.c.toLowerCase());
    if (s > bestScore) {
      bestScore = s;
      best = item;
    }
  }

  if (best && bestScore >= 4) {
    return new Response(JSON.stringify({
      ok: true,
      img: best.u,
      caption: best.c,
      source: 'wol.jw.org'
    }), {
      status: 200,
      headers: { 'Content-Type': 'application/json', 'Cache-Control': 'public, max-age=86400', 'Access-Control-Allow-Origin': '*' }
    });
  }

  // Live fallback to wol.jw.org search
  try {
    const searchUrl = 'https://wol.jw.org/en/wol/s/r1/lp-e?q=' + encodeURIComponent(q) + '&p=par';
    const sr = await fetch(searchUrl, { headers: { 'User-Agent': 'Mozilla/5.0' } });
    if (sr.ok) {
      const sHtml = await sr.text();
      const docMatches = [...sHtml.matchAll(/\/en\/wol\/d\/r1\/lp-e\/\d+/g)].map(m => m[0]);
      const uniqueDocs = [...new Set(docMatches)].slice(0, 3);
      for (const docPath of uniqueDocs) {
        const dr = await fetch('https://wol.jw.org' + docPath, { headers: { 'User-Agent': 'Mozilla/5.0' } });
        if (!dr.ok) continue;
        const dHtml = await dr.text();
        const imgRegex = /<img[^>]+\bsrc="(\/en\/wol\/mp\/[^"]+)"[^>]*>/gi;
        let m;
        while ((m = imgRegex.exec(dHtml)) !== null) {
          const tag = m[0];
          if (tag.includes('cardThumbnailImage') || tag.includes('sharePublicationImage') || tag.includes('lightbox')) continue;
          const altMatch = tag.match(/\balt="([^"]*)"/i);
          return new Response(JSON.stringify({
            ok: true,
            img: 'https://wol.jw.org' + m[1],
            caption: altMatch ? altMatch[1] : q,
            source: 'wol.jw.org'
          }), {
            status: 200,
            headers: { 'Content-Type': 'application/json', 'Cache-Control': 'public, max-age=86400', 'Access-Control-Allow-Origin': '*' }
          });
        }
      }
    }
  } catch (e) {
    // Ignore live search error
  }

  return new Response(JSON.stringify({ ok: false, error: 'not_found' }), {
    status: 404,
    headers: { 'Content-Type': 'application/json', 'Access-Control-Allow-Origin': '*' }
  });
}
